Component(
  dsl: 1, id: "market/collection-info", name: "Collection info", kind: Kind.section,
  description: "Where to collect, shown only when the store offers collection.",
  variants: [Variant(id: "default", label: "Default", build:
    If(condition: store.accepts_collect, then: Box(padding: Space.md, radius: Radius.md, background: Color.surfaceAlt, child: Row(gap: Space.sm, crossAxisAlignment: CrossAxisAlignment.center, children: [
      Icon(name: Icons.home, color: Color.primary),
      Expanded(child: Column(gap: Space.xs, children: [Text(child: "Collect it yourself", weight: FontWeight.semibold), Text(child: "${store.address_line1}, ${store.city}", size: FontSize.sm, color: Color.textMuted)]))
    ])))
  )], data: [Data(name: "store", from: Client.store(), fetch: "client", type: Store)],
)
